function Report=run_p1_aerospace_w2e(sourceRoot,varargin)
%RUN_P1_AEROSPACE_W2E One-click paired 500-trial Proposed vs Matched-QP campaign.
% MATLAB R2018a. Pair-level PARFOR. Exact saved Rev.4.1.1 Samples are reused.
p=inputParser;p.addRequired('sourceRoot',@ischar);p.addParameter('UseParallel',true,@(x)islogical(x)||ismember(x,[0 1]));p.addParameter('NumWorkers',56,@(x)isnumeric(x)&&isscalar(x)&&x>=1);p.addParameter('Resume',true,@(x)islogical(x)||ismember(x,[0 1]));p.parse(sourceRoot,varargin{:});A=p.Results;
packageRoot=fileparts(mfilename('fullpath'));oldPath=path;oldPwd=pwd;cd(packageRoot);addpath(sourceRoot,'-begin');addpath(packageRoot,'-begin');rehash path;cleanupPath=onCleanup(@()local_restore(oldPath,oldPwd)); %#ok<NASGU>
sourceRoot=local_normalize_source(sourceRoot);O=w2e_options();O.UseParallel=logical(A.UseParallel);O.RequestedWorkers=round(A.NumWorkers);O.Resume=logical(A.Resume);
outdir=[sourceRoot '_W2E_PairedMC500_rho010_v1_0'];if exist(outdir,'dir')~=7,mkdir(outdir);end;logfile=fullfile(outdir,'W2E_console_log.txt');diary(logfile);cleanupDiary=onCleanup(@()local_diary_off()); %#ok<NASGU>
fprintf('\n============================================================\nPaper 1 -> Aerospace | W2-E paired 500-trial Monte Carlo\n============================================================\n');fprintf('Version  : %s\nProtocol : %s\nMATLAB   : %s\nSource   : %s\nPackage  : %s\nOutput   : %s\n',O.Version,O.ProtocolID,version,sourceRoot,packageRoot,outdir);fprintf('Pairs    : 500 saved uncertainty records x {Proposed, MatchedQP} = 1000 full-6DOF runs\nWorkers  : requested %d process workers\nrhoB     : %.2f (in memory only)\n',O.RequestedWorkers,O.RhoB);fprintf('No source file is modified. No new uncertainty sample is generated for the campaign.\n');
Pre=w2e_preflight(sourceRoot,outdir,O);Samples=Pre.Samples;Rmc=Pre.Rmc;Cbase=Pre.Cbase;fprintf('PREFLIGHT PASS: exact source identity, exact saved Samples, 18 hard rows, locked QP metric.\n');fprintf('Frozen sample file SHA256: %s\n',Pre.SampleHash);
InitialAudit=w2e_initial_screen(Samples,Rmc,Cbase,O,outdir);fprintf('INITIAL SCREEN PASS: %d/%d frozen samples are raw-chart regular, inside K_B(0.10), backup-candidate feasible, and solvable by both selectors at t=0.\n',InitialAudit.N,InitialAudit.N);
ckFile=fullfile(outdir,'W2E_CHECKPOINT.mat');PairResults=cell(O.N,1);if O.Resume&&exist(ckFile,'file')==2,L=load(ckFile,'PairResultsSaved','ProtocolIDSaved','SampleHashSaved');if isfield(L,'ProtocolIDSaved')&&strcmp(L.ProtocolIDSaved,O.ProtocolID)&&strcmp(L.SampleHashSaved,Pre.SampleHash)&&numel(L.PairResultsSaved)==O.N,PairResults=L.PairResultsSaved;fprintf('Checkpoint loaded: %d/%d pairs already committed.\n',sum(~cellfun(@isempty,PairResults)),O.N);else,error('W2E:CheckpointIdentity','Existing checkpoint identity does not match frozen protocol/sample source. Move the output folder rather than overwriting it.');end;end
pending=find(cellfun(@isempty,PairResults));fprintf('\nPART A -- paired full-6DOF campaign\nPending pairs: %d/%d\n',numel(pending),O.N);
if isempty(pending),P=struct('Enabled',false,'Workers',0,'CreatedByRunner',false,'Mode','RESUME_COMPLETE','Message','All pairs already committed.');pool=[];else,[P,pool]=w2e_parallel_prepare(O.UseParallel,O.RequestedWorkers,numel(pending),sourceRoot,packageRoot,outdir);end
if P.Enabled,batchSize=max(P.PoolSize*O.BatchPairsPerWorker,P.PoolSize);else,batchSize=1;end;wall=tic;
try
 for ib=1:batchSize:numel(pending)
  idx=pending(ib:min(ib+batchSize-1,numel(pending)));nB=numel(idx);fprintf('\nBATCH %d-%d of pending list: %d pairs (trial indices %d ... %d)\n',ib,min(ib+batchSize-1,numel(pending)),nB,idx(1),idx(end));Batch=cell(nB,1);bt=tic;
  if P.Enabled,parfor jj=1:nB,k=idx(jj);Batch{jj}=w2e_run_pair(Samples(k),Rmc,Cbase,O);end,else,for jj=1:nB,k=idx(jj);Batch{jj}=w2e_run_pair(Samples(k),Rmc,Cbase,O);end,end
  for jj=1:nB,PairResults{idx(jj)}=Batch{jj};end
  PairResultsSaved=PairResults;ProtocolIDSaved=O.ProtocolID;SampleHashSaved=Pre.SampleHash;save(ckFile,'PairResultsSaved','ProtocolIDSaved','SampleHashSaved','-v7.3');
  done=~cellfun(@isempty,PairResults);PD=PairResults(done);bp=0;dc=0;pOnly=0;qOnly=0;for z=1:numel(PD),bp=bp+PD{z}.Pair.BothCorePass;dc=dc+PD{z}.Pair.ExecutionDiscordant;pOnly=pOnly+PD{z}.Pair.ProposedOnlyCorePass;qOnly=qOnly+PD{z}.Pair.QPOnlyCorePass;end
  fprintf('Batch wall %.1f s | committed %d/%d | both-CorePass=%d | Proposed-only=%d | QP-only=%d | execution-discordant=%d\n',toc(bt),sum(done),O.N,bp,pOnly,qOnly,dc);
 end
catch ME
 try,w2e_parallel_finish(pool,P,sourceRoot,packageRoot,outdir);catch,end;pool=[];rethrow(ME);
end
totalWall=toc(wall);PoolFinish=w2e_parallel_finish(pool,P,sourceRoot,packageRoot,outdir);pool=[];fprintf('%s\n',PoolFinish.Message);
if any(cellfun(@isempty,PairResults)),Decision='HOLD_INCOMPLETE_CHECKPOINT';fprintf(2,'Campaign is incomplete: %d/%d pairs committed. Rerun the same command with Resume=true.\n',sum(~cellfun(@isempty,PairResults)),O.N);Report=struct('Timestamp',datestr(now,31),'Version',O.Version,'ProtocolID',O.ProtocolID,'Decision',Decision,'Options',O,'Preflight',Pre,'InitialAudit',InitialAudit,'PairResults',{PairResults},'Parallel',P,'ParallelFinish',PoolFinish,'WallTime_s',totalWall);save(fullfile(outdir,'W2E_PARTIAL_Report.mat'),'Report','-v7.3');return;end
fprintf('\nPART B -- frozen outcome and paired-statistics audit\n');Summary=w2e_summarize_all(PairResults,Samples,O,Rmc);Decision='PASS_W2E_CAMPAIGN_COMPLETED_FOR_RESULT_AUDIT';fprintf('Proposed : completed=%d core=%d certified=%d domainExit=%d numerical=%d\n',Summary.Proposed.NCompleted,Summary.Proposed.NCorePass,Summary.Proposed.NCertifiedDomain,Summary.Proposed.NDomainExit,Summary.Proposed.NNumericalFailure);fprintf('MatchedQP: completed=%d core=%d certified=%d domainExit=%d numerical=%d\n',Summary.MatchedQP.NCompleted,Summary.MatchedQP.NCorePass,Summary.MatchedQP.NCertifiedDomain,Summary.MatchedQP.NDomainExit,Summary.MatchedQP.NNumericalFailure);fprintf('Pairs    : bothCore=%d, ProposedOnly=%d, QPOnly=%d, neither=%d, executionDiscordant=%d\n',Summary.Pair.NBothCorePass,Summary.Pair.NProposedOnlyCorePass,Summary.Pair.NQPOnlyCorePass,Summary.Pair.NNeitherCorePass,Summary.Pair.NExecutionDiscordant);
Report=struct('Timestamp',datestr(now,31),'Version',O.Version,'ProtocolID',O.ProtocolID,'SourceRoot',sourceRoot,'PackageRoot',packageRoot,'OutputDir',outdir,'Options',O,'Preflight',rmfield(Pre,{'Samples','Cbase'}),'InitialAudit',InitialAudit,'Samples',Samples,'PairResults',{PairResults},'Summary',Summary,'Parallel',P,'ParallelFinish',PoolFinish,'CampaignWallTime_s',totalWall,'Decision',Decision,'Interpretation','Empirical paired study under the stated artificial uncertainty ensemble; no universal method ranking or real-world reliability probability.');Files=w2e_export(outdir,PairResults,Samples,Summary,Report,O);Report.Files=Files;save(fullfile(outdir,'W2E_Report.mat'),'Report','-v7.3');
fprintf('\n============================================================\nW2-E DECISION: %s\n============================================================\n',Decision);fprintf('Continuous pair deltas use BOTH_CORE_PASS pairs only; every one of the 500 outcome pairs remains in the outcome ledger.\n');fprintf('Parallel campaign wall time is execution telemetry only, NOT a publication algorithm-runtime benchmark.\n');diary off;zipPath=[outdir '.zip'];try,if exist(zipPath,'file')==2,delete(zipPath);end;zip(zipPath,{'*'},outdir);fprintf('Output ZIP: %s\n',zipPath);catch ME,fprintf(2,'ZIP creation failed: %s\n',ME.message);end;fprintf('Output directory: %s\n',outdir);
end
function p=local_normalize_source(p),while numel(p)>1&&(p(end)=='/'||p(end)==char(92)),p(end)=[];end;if exist(fullfile(p,'rg_params.m'),'file')==2,return;end;error('W2E:Source','sourceRoot must directly contain rg_params.m.');end
function local_restore(oldPath,oldPwd),try,path(oldPath);catch,end;try,if exist(oldPwd,'dir')==7,cd(oldPwd);end;catch,end,end
function local_diary_off(),try,diary off;catch,end,end
